let dashboard,activeConversationId;const notice=document.getElementById('dashboardNotice');async function api(path,options={}){const response=await fetch(path,{headers:{'Content-Type':'application/json'},...options}),data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');return data}function initials(name){return String(name).split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase()}function escapeHtml(value){return String(value||'').replace(/[&<>'"]/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'})[character])}function showNotice(message,error=false){notice.textContent=message;notice.hidden=false;notice.classList.toggle('error',error);setTimeout(()=>{notice.hidden=true},4000)}function capabilityText(company){return company.capabilities.map(value=>value==='contractor'?'Hires subcontractors':'Finds trade work').join(' + ')}function switchView(name){document.querySelectorAll('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===name));document.querySelectorAll('.dashboard-view').forEach(view=>{view.hidden=view.id!==`${name}View`});if(name==='messages')renderConversations()}document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>switchView(button.dataset.view)));document.getElementById('signOut').addEventListener('click',async()=>{await api('/api/logout',{method:'POST'});location.href='/'});document.getElementById('primaryAction').addEventListener('click',()=>switchView('network'));
function renderShell(){const{company,user,conversations,directory,connections}=dashboard,roles=capabilityText(company),accepted=connections.filter(item=>item.status==='accepted'),pendingIncoming=connections.filter(item=>item.status==='pending'&&item.direction==='incoming'),unread=conversations.reduce((sum,item)=>sum+item.unread,0);document.getElementById('navInitials').textContent=initials(company.name);document.getElementById('navCompany').textContent=company.name;document.getElementById('navRole').textContent=roles;document.getElementById('dashboardGreeting').textContent=`Welcome back, ${user.fullName.split(' ')[0]}.`;document.getElementById('dashboardKicker').textContent=company.capabilities.length>1?'Full marketplace workspace':company.capabilities[0]==='contractor'?'Contractor workspace':'Subcontractor workspace';document.getElementById('unreadCount').textContent=unread||'';document.getElementById('networkCount').textContent=pendingIncoming.length||'';document.getElementById('statGrid').innerHTML=`<div><span>Trusted network</span><strong>${accepted.length}</strong><small>accepted trade partners</small></div><div><span>Unread messages</span><strong>${unread}</strong><small>need your attention</small></div><div><span>Referrals</span><strong>${dashboard.referrals.length}</strong><small>opportunities shared</small></div><div><span>Invites sent</span><strong>${dashboard.invites.length}</strong><small>partners invited</small></div>`;document.getElementById('setupSteps').innerHTML=`<div class="setup-item done"><span>1</span><div><strong>Company account created</strong><small>${escapeHtml(roles)}</small></div></div><div class="setup-item ${accepted.length?'done':''}"><span>2</span><div><strong>Build your trusted trade network</strong><small>Connect with people whose work you know.</small></div></div><div class="setup-item"><span>3</span><div><strong>${company.capabilities.includes('contractor')?'Post your first job':'Complete your trade portfolio'}</strong><small>Unlock the core marketplace workflow.</small></div></div>`;document.getElementById('profileCompany').textContent=company.name;document.getElementById('profileDetails').innerHTML=`<dl><div><dt>Capabilities</dt><dd>${escapeHtml(roles)}</dd></div><div><dt>Location</dt><dd>${escapeHtml([company.city,company.state].filter(Boolean).join(', '))}</dd></div><div><dt>Trades</dt><dd>${escapeHtml(company.trades.join(', ')||'Not added yet')}</dd></div><div><dt>Account owner</dt><dd>${escapeHtml(user.fullName)} · ${escapeHtml(user.email)}</dd></div></dl>`;renderDirectory();renderNetwork();renderReferrals();renderConversations()}
function conversationMarkup(item){return`<button type="button" class="conversation-item ${item.id===activeConversationId?'active':''}" data-conversation="${item.id}"><span class="company-mark">${initials(item.otherCompany.name)}</span><div><strong>${escapeHtml(item.otherCompany.name)}</strong><small>${escapeHtml(item.lastMessage?.body||'Conversation ready')}</small></div>${item.unread?`<b>${item.unread}</b>`:''}</button>`}function renderConversations(){const html=dashboard.conversations.length?dashboard.conversations.map(conversationMarkup).join(''):'<div class="list-empty">No conversations yet. Open your trade network to meet another company.</div>';document.getElementById('conversationList').innerHTML=html;document.getElementById('recentConversations').innerHTML=html;document.querySelectorAll('[data-conversation]').forEach(button=>button.addEventListener('click',()=>openConversation(button.dataset.conversation)))}
function companyCard(company,actions,status=''){return`<article class="directory-card"><span class="company-mark">${initials(company.name)}</span><div>${status?`<span class="connection-status ${status==='accepted'?'accepted':''}">${escapeHtml(status)}</span>`:`<span class="trade-pill">${escapeHtml(company.state||'Nationwide')}</span>`}<h3>${escapeHtml(company.name)}</h3><p>${escapeHtml(capabilityText(company))}</p><small>${escapeHtml(company.trades.join(' · ')||'Trades profile in progress')}</small></div><div class="connection-actions">${actions}</div></article>`}function renderDirectory(){const available=dashboard.directory.filter(company=>company.connectionStatus==='none');document.getElementById('directoryGrid').innerHTML=available.length?available.map(company=>companyCard(company,`<button class="button button-outline" type="button" data-request="${company.id}">Connect</button><button class="text-link" type="button" data-connect="${company.id}">Message</button>`)).join(''):'<div class="list-empty">No new companies to discover right now. Invite someone you trust.</div>';document.querySelectorAll('[data-connect]').forEach(button=>button.addEventListener('click',()=>startConversation(button.dataset.connect)));document.querySelectorAll('[data-request]').forEach(button=>button.addEventListener('click',()=>requestConnection(button.dataset.request)))}
function renderNetwork(){const accepted=dashboard.connections.filter(item=>item.status==='accepted'),requests=dashboard.connections.filter(item=>item.status==='pending');document.getElementById('connectionGrid').innerHTML=accepted.length?accepted.map(item=>companyCard(item.otherCompany,`<button class="button button-outline" type="button" data-connect="${item.otherCompany.id}">Message</button><button class="text-link" type="button" data-refer="${item.otherCompany.id}">Refer job</button>`,'accepted')).join(''):'<div class="list-empty">Accepted trade partners will appear here.</div>';document.getElementById('requestGrid').innerHTML=requests.length?requests.map(item=>companyCard(item.otherCompany,item.direction==='incoming'?`<button class="button button-orange" type="button" data-respond-connection="${item.id}" data-status="accepted">Accept</button><button class="text-link" type="button" data-respond-connection="${item.id}" data-status="declined">Decline</button>`:'<span class="muted">Waiting for response</span>','pending')).join(''):'<div class="list-empty">No pending requests.</div>';const select=document.getElementById('referralCompany');select.innerHTML=accepted.length?'<option value="">Choose a trusted connection</option>'+accepted.map(item=>`<option value="${item.otherCompany.id}">${escapeHtml(item.otherCompany.name)}</option>`).join(''):'<option value="">Connect with a company first</option>';document.querySelectorAll('[data-connect]').forEach(button=>button.addEventListener('click',()=>startConversation(button.dataset.connect)));document.querySelectorAll('[data-refer]').forEach(button=>button.addEventListener('click',()=>{select.value=button.dataset.refer;document.getElementById('referralForm').scrollIntoView({behavior:'smooth'})}));document.querySelectorAll('[data-respond-connection]').forEach(button=>button.addEventListener('click',()=>respondConnection(button.dataset.respondConnection,button.dataset.status)))}
function renderReferrals(){document.getElementById('referralGrid').innerHTML=dashboard.referrals.length?dashboard.referrals.map(item=>`<article class="referral-card"><span class="connection-status ${item.status==='interested'?'accepted':''}">${escapeHtml(item.status)}</span><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.note||'No additional note')}</p><small>${item.direction==='incoming'?'From':'To'} ${escapeHtml(item.otherCompany.name)}</small>${item.direction==='incoming'&&item.status==='sent'?`<div class="connection-actions"><button class="button button-orange" type="button" data-referral="${item.id}" data-status="interested">Interested</button><button class="text-link" type="button" data-referral="${item.id}" data-status="passed">Pass</button></div>`:''}</article>`).join(''):'<div class="list-empty">Job referrals shared with trusted connections will appear here.</div>';document.querySelectorAll('[data-referral]').forEach(button=>button.addEventListener('click',()=>respondReferral(button.dataset.referral,button.dataset.status)))}
async function requestConnection(companyId){try{await api('/api/network/requests',{method:'POST',body:JSON.stringify({companyId,note:'I would like to add you to my trusted trade network.'})});await refresh();showNotice('Connection request sent.')}catch(error){showNotice(error.message,true)}}async function respondConnection(connectionId,status){try{await api(`/api/network/requests/${connectionId}/respond`,{method:'POST',body:JSON.stringify({status})});await refresh();showNotice(status==='accepted'?'Trade partner added to your network.':'Request declined.')}catch(error){showNotice(error.message,true)}}async function respondReferral(referralId,status){try{await api(`/api/referrals/${referralId}/respond`,{method:'POST',body:JSON.stringify({status})});await refresh();showNotice('Referral updated.')}catch(error){showNotice(error.message,true)}}
document.getElementById('inviteForm').addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.currentTarget);try{const result=await api('/api/network/invites',{method:'POST',body:JSON.stringify(Object.fromEntries(form))}),url=`${location.origin}${result.signupPath}`,box=document.getElementById('inviteResult');box.innerHTML=`Invite ready. Share this private signup link:<br><strong>${escapeHtml(url)}</strong>`;box.hidden=false;await refresh();showNotice('Invite link created.')}catch(error){showNotice(error.message,true)}});document.getElementById('referralForm').addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.currentTarget);try{await api('/api/referrals',{method:'POST',body:JSON.stringify(Object.fromEntries(form))});event.currentTarget.reset();await refresh();showNotice('Job referral sent to your trade partner.')}catch(error){showNotice(error.message,true)}});
async function startConversation(companyId){try{const result=await api('/api/conversations',{method:'POST',body:JSON.stringify({companyId})});await refresh();switchView('messages');await openConversation(result.conversation.id)}catch(error){showNotice(error.message,true)}}async function openConversation(conversationId){try{activeConversationId=conversationId;const result=await api(`/api/conversations/${conversationId}/messages`);document.getElementById('messageEmpty').hidden=true;document.getElementById('messageWorkspace').hidden=false;document.getElementById('messageInitials').textContent=initials(result.otherCompany.name);document.getElementById('messageCompany').textContent=result.otherCompany.name;document.getElementById('messageMeta').textContent=`${capabilityText(result.otherCompany)} · ${[result.otherCompany.city,result.otherCompany.state].filter(Boolean).join(', ')}`;document.getElementById('messageThread').innerHTML=result.messages.length?result.messages.map(message=>`<div class="message-bubble ${message.senderCompanyId===dashboard.company.id?'mine':''}"><strong>${escapeHtml(message.senderName)}</strong><p>${escapeHtml(message.body)}</p><small>${new Date(message.createdAt).toLocaleString()}</small></div>`).join(''):'<div class="message-empty compact"><span>Start the conversation. Introduce your company or discuss a project opportunity.</span></div>';document.getElementById('messageThread').scrollTop=document.getElementById('messageThread').scrollHeight;renderConversations()}catch(error){showNotice(error.message,true)}}document.getElementById('messageForm').addEventListener('submit',async event=>{event.preventDefault();if(!activeConversationId)return;const field=event.currentTarget.elements.body;try{await api(`/api/conversations/${activeConversationId}/messages`,{method:'POST',body:JSON.stringify({body:field.value})});field.value='';await refresh();await openConversation(activeConversationId)}catch(error){showNotice(error.message,true)}});async function refresh(){dashboard=await api('/api/dashboard');renderShell()}refresh().then(()=>{if(location.pathname==='/network')switchView('network');if(location.pathname==='/messages')switchView('messages')}).catch(()=>{location.href='/login'});
